// ✅ Async, with the decode explicitly off the main actor
@MainActor
final class FeedModel {
  var feed: [Post] = []

  func load() async {
    do {
      let (data, _) = try await URLSession.shared.data(from: hugeURL)
      feed = try await Self.decode(data)                // hops back on return
    } catch {
      // surface to the UI
    }
  }

  // @concurrent (Swift 6.2) keeps this off the main actor even in a module
  // that defaults to main-actor isolation
  @concurrent
  nonisolated static func decode(_ data: Data) async throws -> [Post] {
    try JSONDecoder().decode([Post].self, from: data)
  }
}

