// Also avoid: Objective-C +load methods, and dozens of small dynamic
// frameworks — each one is dyld work on every cold launch.

func thumbnail(from url: URL, maxPixel: CGFloat, scale: CGFloat) -> UIImage? {
  let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
  guard let source = CGImageSourceCreateWithURL(url as CFURL, sourceOptions) else { return nil }

  let options: [CFString: Any] = [
    kCGImageSourceCreateThumbnailFromImageAlways: true,
    kCGImageSourceShouldCacheImmediately: true,       // decode now, off the main thread
    kCGImageSourceCreateThumbnailWithTransform: true,
    kCGImageSourceThumbnailMaxPixelSize: maxPixel * scale
  ]
  guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary)
  else { return nil }
  return UIImage(cgImage: cgImage, scale: scale, orientation: .up)
}

// Bounded cache: NSCache evicts under pressure, a Dictionary never does
let cache = NSCache<NSURL, UIImage>()
cache.countLimit = 200
cache.totalCostLimit = 64 << 20

// Temporaries die per iteration instead of at the end of the loop
for url in urls {
  autoreleasepool {
    if let image = thumbnail(from: url, maxPixel: 120, scale: 3) {
      cache.setObject(image, forKey: url as NSURL)
    }
  }
}

