// Fast row: precomputed values, stable identity, sized image
struct GoodRow: View, Equatable {
  let post: PostViewData                     // formatted once, upstream

  var body: some View {
    let _ = Self._printChanges()             // why did this re-run?
    HStack {
      ThumbnailView(url: post.imageURL)
        .frame(width: 44, height: 44)
      Text(post.formattedDate)
    }
  }

  static func == (lhs: GoodRow, rhs: GoodRow) -> Bool { lhs.post.id == rhs.post.id }
}

