// Batch events; flush on background or when the buffer fills
actor AnalyticsQueue {
  private var buffer: [Event] = []

  func track(_ event: Event) async {
    buffer.append(event)
    if buffer.count >= 50 { await flush() }
  }

  func flush() async {
    guard !buffer.isEmpty else { return }
    let batch = buffer
    buffer.removeAll()
    try? await api.send(batch)          // one request, not fifty
  }
}

