// On-Demand Resources: tagged content is downloaded on first use
final class TutorialAssets {
  private var request: NSBundleResourceRequest?

  func load() async throws -> URL {
    let request = NSBundleResourceRequest(tags: ["tutorial-videos"])
    request.loadingPriority = NSBundleResourceRequestLoadingPriorityUrgent
    self.request = request

    try await request.beginAccessingResources()
    return Bundle.main.url(forResource: "intro", withExtension: "mp4")!
  }

  func release() {
    request?.endAccessingResources()   // lets the system purge it again
    request = nil
  }
}

