// Thread explosion: 200 blocked threads, none of them making progress
for url in urls {
  DispatchQueue.global().async {
    let data = try? Data(contentsOf: url)     // blocks a thread for the whole transfer
    handle(data)
  }
}

// Bounded, non-blocking: the pool stays at core count and suspends at await
try await withThrowingTaskGroup(of: Data.self) { group in
  for url in urls.prefix(6) { group.addTask { try await fetch(url) } }
  var remaining = urls.dropFirst(6).makeIterator()
  for try await data in group {
    handle(data)
    if let next = remaining.next() { group.addTask { try await fetch(next) } }
  }
}

// Blocking C or legacy API: keep it off the cooperative pool
private let legacyQueue = DispatchQueue(label: "legacy.decoder")

func decode(_ data: Data) async -> Frame {
  await withCheckedContinuation { continuation in
    legacyQueue.async { continuation.resume(returning: blockingDecode(data)) }
  }
}

