// Field data: the only numbers that describe real devices
import MetricKit

final class MetricsReporter: NSObject, MXMetricManagerSubscriber {
  func didReceive(_ payloads: [MXMetricPayload]) {
    for payload in payloads {
      let launch = payload.applicationLaunchMetrics?.histogrammedTimeToFirstDraw
      let hangs = payload.applicationResponsivenessMetrics?.histogrammedApplicationHangTime
      upload(launch: launch, hangs: hangs)
    }
  }
}
